  ('4d7fe32f-bdd3-5df2-909d-a421f59699b6', null, (select id from public.skills where slug = 'write-g5-precise-language'), null, 'hard',
   $q$Read the sentence: "At 3:00 p.m. in the afternoon, the chorus sang together in unison." Which revision removes all the words that repeat an idea?$q$, $q$[{"text":"In the afternoon, the chorus sang.","is_correct":false,"misconception_token":"drops-meaning"},{"text":"At 3:00 p.m., the chorus sang in unison.","is_correct":true},{"text":"At 3:00 p.m. in the afternoon, the chorus sang in unison.","is_correct":false,"misconception_token":"still-redundant"},{"text":"At 3:00 p.m., the chorus sang together in unison.","is_correct":false,"misconception_token":"partly-redundant"}]$q$::jsonb, $q$At 3:00 p.m., the chorus sang in unison.$q$, $q$"P.m." already means afternoon, and "in unison" already means together, so both extras can go. "At 3:00 p.m., the chorus sang together in unison." fixes the time but still says "together in unison."$q$, 'draft', null)
