  ('f3be4c33-3384-5f26-8f92-117b4007500c', null, (select id from public.skills where slug = 'write-g5-precise-language'), null, 'hard',
   $q$Read the sentences: "The Millbrook Canal opened in 1825. The canal connected Lake Avery to the Pine River." Which choice best combines the sentences?$q$, $q$[{"text":"The Millbrook Canal, which connected Lake Avery, opened in 1825 to the Pine River.","is_correct":false,"misconception_token":"misplaced-modifier"},{"text":"Lake Avery opened in 1825 and connected the Millbrook Canal to the Pine River.","is_correct":false,"misconception_token":"changes-meaning"},{"text":"The Millbrook Canal opened in 1825, it connected Lake Avery to the Pine River.","is_correct":false,"misconception_token":"comma-splice-unfixed"},{"text":"The Millbrook Canal, which opened in 1825, connected Lake Avery to the Pine River.","is_correct":true}]$q$::jsonb, $q$The Millbrook Canal, which opened in 1825, connected Lake Avery to the Pine River.$q$, $q$The "which" clause tucks the opening date beside the canal's name and keeps the rest in order. "The Millbrook Canal, which connected Lake Avery, opened in 1825 to the Pine River." splits "Lake Avery to the Pine River," so it no longer makes sense.$q$, 'draft', null)
