  ('65878a93-4425-50f4-8f02-1c8344d3d6b6', null, (select id from public.skills where slug = 'write-g5-precise-language'), null, 'hard',
   $q$Read the sentence: "The frogs were freaking out when the rain started, so they hopped all over the place." Which revision best fits the formal style of a science journal?$q$, $q$[{"text":"When the rain started, the frogs hopped to the pond to lay their eggs.","is_correct":false,"misconception_token":"adds-new-facts"},{"text":"When the rain started, the frogs became very active and hopped in every direction.","is_correct":true},{"text":"When the rain started, the frogs totally went wild and hopped everywhere.","is_correct":false,"misconception_token":"too-informal"},{"text":"When the rain started, the frogs hopped.","is_correct":false,"misconception_token":"drops-meaning"}]$q$::jsonb, $q$When the rain started, the frogs became very active and hopped in every direction.$q$, $q$"Became very active" and "in every direction" replace the slang with clear, formal words while keeping the meaning. "Totally went wild" is still casual, like "freaking out."$q$, 'draft', null)
