  ('303418b7-927b-55b6-81ac-5a48cbca1ec1', null, (select id from public.skills where slug = 'write-g6-argument-writing'), null, 'medium',
   $q$Which piece of evidence would best support sentence (4)?$q$, $q$[{"text":"Many students say their favorite school lunch is pizza on Fridays.","is_correct":false,"misconception_token":"off-topic-evidence"},{"text":"The first postage stamp was printed almost two hundred years ago.","is_correct":false,"misconception_token":"irrelevant-detail"},{"text":"A teacher survey found that letters written to pen pals had fewer spelling errors than regular class assignments.","is_correct":true},{"text":"The writer once wrote a thank you note to a neighbor and liked it.","is_correct":false,"misconception_token":"weak-anecdote"}]$q$::jsonb, $q$A teacher survey found that letters written to pen pals had fewer spelling errors than regular class assignments.$q$, $q$Sentence (4) says students take more care when a real person will read their work, and the survey shows fewer errors in pen pal letters. The writer's single thank you note does not show anything about how carefully students write.$q$, 'draft', '4a1d66de-fe3c-5482-9c57-7e168e6035b5')
