-- Passage wg6-argument-writing-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('ee5a62a6-c7ea-5541-82be-b8ea441a37dc', 'wg6-argument-writing-p02', (select id from public.skills where slug = 'write-g6-argument-writing'), null,
        '6-8', $q$Shade for Main Street$q$, $q$(1) On summer afternoons, the sidewalks on Main Street in Pinecrest become so hot that many people avoid walking there, even to reach their favorite shops. (2) The town has many problems. (3) Trees cool the air around them by shading the ground and releasing water through their leaves. (4) Our county parks department measured shaded sidewalks that were up to fifteen degrees cooler than sunny ones. (5) Cooler sidewalks would bring more shoppers, which would help the small businesses on the street.

(6) Some business owners argue that tree roots could crack the sidewalks. (7) ______ city planners can choose kinds of trees whose roots grow deep instead of spreading sideways. (8) Planters with root barriers can also protect the pavement around each tree for many years.

(9) Trees would make Main Street cooler, friendlier, and better for business. (10) I think trees are pretty and stuff, so whatever.$q$, 'draft')
on conflict (id) do update set title = excluded.title, body = excluded.body
where public.passages.status = 'draft';
insert into public.generated_questions
  (id, template_id, skill_id, sat_alignment, difficulty, stem, choices, correct_answer, solution, status, passage_id)
values
  ('309bfac5-e732-50a9-8269-179c24cc0394', null, (select id from public.skills where slug = 'write-g6-argument-writing'), null, 'easy',
   $q$Sentence (2) does not state a clear claim. Which revision of sentence (2) is best?$q$, $q$[{"text":"Pinecrest should plant shade trees along Main Street to cool the sidewalks and help local shops.","is_correct":true},{"text":"Summer in Pinecrest can be very hot for many weeks in a row.","is_correct":false,"misconception_token":"too-vague"},{"text":"Main Street is one of the oldest streets in Pinecrest.","is_correct":false,"misconception_token":"fact-not-claim"},{"text":"Some people like trees on their streets, and some people do not.","is_correct":false,"misconception_token":"no-position"}]$q$::jsonb, $q$Pinecrest should plant shade trees along Main Street to cool the sidewalks and help local shops.$q$, $q$The correct revision takes a clear position that the rest of the essay supports. The sentence about hot summers is true but does not tell readers what the writer wants the town to do.$q$, 'draft', 'ee5a62a6-c7ea-5541-82be-b8ea441a37dc')
