  ('4fb4a219-9651-54db-8a7d-75041c2bcba1', null, (select id from public.skills where slug = 'write-g6-argument-writing'), null, 'easy',
   $q$Which transition best fills the blank at the beginning of sentence (7)?$q$, $q$[{"text":"For instance,","is_correct":false,"misconception_token":"example-for-contrast"},{"text":"Also,","is_correct":false,"misconception_token":"addition-for-contrast"},{"text":"Because of this,","is_correct":false,"misconception_token":"cause-effect-for-contrast"},{"text":"However,","is_correct":true}]$q$::jsonb, $q$However,$q$, $q$Sentence (7) answers the business owners' worry in sentence (6), so a contrast word like "However" is needed. "For instance" would wrongly treat sentence (7) as an example of roots cracking sidewalks.$q$, 'draft', 'ee5a62a6-c7ea-5541-82be-b8ea441a37dc')
