-- Passage wg6-narrative-writing-p02
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('04e95910-35e4-5536-b2f8-12df363a0c07', 'wg6-narrative-writing-p02', (select id from public.skills where slug = 'write-g6-narrative-writing'), null,
        '6-8', $q$The Number 9 Bus$q$, $q$(1) Last Saturday, Mom let me ride the Number 9 bus to the library without her for the first time. (2) My little sister, Ama, begged to come, so Mom said I was in charge of both of us. (3) I had the route memorized: six stops, then get off at Maple Street. (4) We sat in the second row, right behind the driver. (5) At each stop, I counted on my fingers. (6) Ama kept asking me questions about the people getting on. (7) Kofi felt proud of himself for remembering everything. (8) At the fourth stop, the driver announced that the bus was taking a detour because of road work. (9) My stomach dropped. (10) The bus turned left onto a street I had never seen.

(11) I took a deep breath and looked out the window for anything I knew. (12) Then I spotted the tall clock on the bank, the one Mom always points out. (13) The library was only two blocks past it. (14) I pressed the stop button, and we stepped off onto the sidewalk.

(15) Ama took my hand as we walked the last two blocks. (16) The library is a good place.$q$, 'draft')
